contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        c.sendMoney(address(c), amount, ""); if (__ESBMC_reverted()) return;

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint callerBefore = address(this).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint callerAfter = address(this).balance;

        assert(
            afterCount == beforeCount &&
            (
                reverted
                    ? (afterBalance == beforeBalance && callerAfter == callerBefore)
                    : (afterBalance == 0 && callerAfter == callerBefore + beforeBalance)
            )
        );
    }

    receive() external payable {}
}

